__device__ __forceinline__ float bf2f(uint32_t v, int half) {
    uint16_t u = (half == 0) ? (uint16_t)(v & 0xffff) : (uint16_t)(v >> 16);
    __nv_bfloat16 b = *reinterpret_cast<__nv_bfloat16*>(&u);
    return __bfloat162float(b);
}

__global__ void probe_kernel(const __nv_bfloat16* d_A, const __nv_bfloat16* d_K,
                             float* d_out /*16x8*/, uint32_t* d_frags, float* d_sA, float* d_sK) {
    __shared__ __align__(16) __nv_bfloat16 sA[16][16];
    __shared__ __align__(16) __nv_bfloat16 sK[8][16];
    int lane = threadIdx.x % 32;
    for (int i = threadIdx.x; i < 16*16; i += 32) sA[i/16][i%16] = d_A[i];
    for (int i = threadIdx.x; i < 8*16; i += 32) sK[i/16][i%16] = d_K[i];
    __syncthreads();
    if (threadIdx.x == 0) {
        for (int r = 0; r < 16; ++r)
            for (int c = 0; c < 16; ++c) d_sA[r*16+c] = __bfloat162float(sA[r][c]);
        for (int r = 0; r < 8; ++r)
            for (int c = 0; c < 16; ++c) d_sK[r*16+c] = __bfloat162float(sK[r][c]);
    }
    __syncthreads();

    uint32_t a[4];
    {
        const int row = ((lane >> 4) << 3) | (lane & 7);
        const int col8 = (lane >> 3) & 1;
        const char* p = reinterpret_cast<const char*>(&sA[row][col8 * 8]);
        ldmatrix_x4(a, p);
    }
    uint32_t b[4];
    {
        const int row = lane & 7;
        const int col8 = (lane >> 3) & 1;
        const char* p = reinterpret_cast<const char*>(&sK[row][col8 * 8]);
        ldmatrix_x4_trans(b, p);
    }
    for (int j = 0; j < 4; ++j) { d_frags[lane * 8 + j] = a[j]; d_frags[256 + lane * 4 + j] = b[j]; }

    float d[4] = {0,0,0,0};
    mma_m16n8k16(d, a, (const uint32_t*)b, d);
    if (threadIdx.x < 32) {
        const int r0 = lane / 4, c0 = 2 * (lane % 4);
        d_out[(r0) * 8 + c0] = d[0];
        d_out[(r0) * 8 + c0 + 1] = d[1];
        d_out[(r0 + 8) * 8 + c0] = d[2];
        d_out[(r0 + 8) * 8 + c0 + 1] = d[3];
    }
}

int main() {
    __nv_bfloat16 hA[16][16], hK[8][16];
    for (int i = 0; i < 16; ++i)
        for (int j = 0; j < 16; ++j) { hA[i][j] = __float2bfloat16((float)(i * 16 + j)); hK[i][j] = __float2bfloat16((float)(1000 + i * 16 + j)); }

    float expD[16][8];
    for (int r = 0; r < 16; ++r)
        for (int c = 0; c < 8; ++c) {
            float s = 0;
            for (int k = 0; k < 16; ++k) s += __bfloat162float(hA[r][k]) * __bfloat162float(hK[c][k]);
            expD[r][c] = s;
        }

    __nv_bfloat16 *dA, *dK; float *dOut, *dsA, *dsK; uint32_t *dF;
    CK(cudaMalloc(&dA, 16*16*2)); CK(cudaMalloc(&dK, 8*16*2));
    CK(cudaMalloc(&dOut, 16*8*4)); CK(cudaMalloc(&dF, 256*4 + 128*4));
    CK(cudaMalloc(&dsA, 16*16*4)); CK(cudaMalloc(&dsK, 8*16*4));
    CK(cudaMemcpy(dA, hA, 16*16*2, cudaMemcpyHostToDevice));
    CK(cudaMemcpy(dK, hK, 8*16*2, cudaMemcpyHostToDevice));
    probe_kernel<<<1, 32>>>(dA, dK, dOut, dF, dsA, dsK);
    CK(cudaDeviceSynchronize());

    float hOut[16*8];
    CK(cudaMemcpy(hOut, dOut, sizeof(hOut), cudaMemcpyDeviceToHost));
    float maxerr = 0;
    for (int r = 0; r < 16; ++r)
        for (int c = 0; c < 8; ++c) maxerr = fmaxf(maxerr, fabsf(hOut[r*8+c] - expD[r][c]));
    printf("D = A*K^T maxerr = %g  %s\n", maxerr, maxerr < 1e-2 ? "PASS" : "FAIL");

    float hsA[256], hsK[128];
    CK(cudaMemcpy(hsA, dsA, sizeof(hsA), cudaMemcpyDeviceToHost));
    CK(cudaMemcpy(hsK, dsK, sizeof(hsK), cudaMemcpyDeviceToHost));
    printf("sA[8][0]=%g sA[8][8]=%g sK[8][0]?=%g (sK has 8 rows; row 8 would be OOB)\n", hsA[8*16], hsA[8*16+8], hsK[8*16]);
    uint32_t hF[256+128];
    CK(cudaMemcpy(hF, dF, sizeof(hF), cudaMemcpyDeviceToHost));
    printf("--- A fragments (lane: a0lo a0hi a1lo a1hi a2lo a2hi a3lo a3hi) ---\n");
    for (int l = 0; l < 8; ++l) {
        printf("lane %d: ", l);
        for (int j = 0; j < 4; ++j)
            printf("(%4.0f,%4.0f) ", bf2f(hF[l*8+j],0), bf2f(hF[l*8+j],1));
        printf("\n");
    }
    printf("--- B fragments (lane: b0lo b0hi b1lo b1hi) ---\n");
    for (int l = 0; l < 8; ++l) {
        printf("lane %d: ", l);
        for (int j = 0; j < 2; ++j)
            printf("(%4.0f,%4.0f) ", bf2f(hF[256+l*4+j],0), bf2f(hF[256+l*4+j],1));
        printf("\n");
    }
    printf("expect A lane0: a0=(A0,0,A0,1)=(0,1) a1=(A0,8,A0,9)=(8,9) a2=(A8,0,A8,1)=(128,129) a3=(A8,8,A8,9)=(136,137)\n");
    printf("expect B lane0: b0=(K0,0,K0,1)=(1000,1001) b1=(K0,8,K0,9)=(1008,1009)\n");
    return 0;
}

